"""Temporary, explicitly loaded mutation probe for Task 4 drain evidence."""
import os

import pytest

import ptest.scheduler as scheduler


@pytest.fixture(autouse=True)
def mutate_drain_predicate(monkeypatch):
    fields = ("pid", "birth", "uid", "pgid")
    selected = os.environ["DRAIN_PREDICATE_MUTATION"]
    removed = fields if selected == "all" else (selected,)
    assert set(removed) <= set(fields)
    original = scheduler.storage.open_database

    class MutatedConnection:
        def __init__(self, conn):
            object.__setattr__(self, "conn", conn)

        def __getattr__(self, name):
            return getattr(self.conn, name)

        def __setattr__(self, name, value):
            setattr(self.conn, name, value)

        def __enter__(self):
            self.conn.__enter__()
            return self

        def __exit__(self, *args):
            return self.conn.__exit__(*args)

        def execute(self, sql, *args):
            if "UPDATE jobs SET state='DRAINING'" in sql:
                parameters = list(args[0])
                for index, field in reversed(tuple(enumerate(fields))):
                    if field in removed:
                        predicate = f"AND guard_{field}=?"
                        assert predicate in sql
                        sql = sql.replace(predicate, "")
                        parameters.pop(6 + index)
                args = (tuple(parameters), *args[1:])
            return self.conn.execute(sql, *args)

    monkeypatch.setattr(
        scheduler.storage, "open_database",
        lambda *args, **kwargs: MutatedConnection(original(*args, **kwargs)),
    )
